import TransportNodeHidSingleton from "@ledgerhq/hw-transport-node-hid-singleton";
import Transport from "@ledgerhq/hw-transport";
import { open } from "@ledgerhq/live-common/hw/index";
import { DisconnectedDeviceDuringOperation, serializeError } from "@ledgerhq/errors";
import { DescriptorEvent } from "@ledgerhq/types-devices";
import { MessagesMap } from "./types";

// Structured responses emitted by the transport handlers.
type DataResponse = { data: unknown };
type BulkResponse = { data: string } | { error: { name: string; message: string } };
type ListenResponse = { data: { type: "add" | "remove"; descriptor: string } };
type CloseResponse = { type: "ok"; data: unknown };

// Store of the currently opened transports, keyed by their device descriptor.
const transports = new Map<string, Transport>();

// Store of active `transportListen` subscribers, keyed by their requestId, so
// that they can be completed from `transportListenUnsubscribe`.
const listenSubscribers = new Map<string, Subscriber<ListenResponse>>();

const getErrorMessage = (error: unknown): string =>
  error instanceof Error ? error.message : String(error);

/**
 * Opens a transport for the given device descriptor.
 *
 * Emits a single response holding the request `data` once a transport is
 * available, then completes. If no registered transport module can handle the
 * descriptor, the underlying `open` rejects with a `CantOpenDevice` error which
 * is forwarded (serialized) through the observable error channel.
 */
export const transportOpen = ({ data }: MessagesMap["transport:open"]) =>
  new Observable<DataResponse>(subscriber => {
    const existing = transports.get(data.descriptor);
    if (existing) {
      subscriber.next({ data });
      subscriber.complete();
      return;
    }

    let cancelled = false;

    open(data.descriptor)
      .then(transport => {
        if (cancelled) {
          // The consumer unsubscribed before the transport was ready: close it
          // to avoid leaking an open connection.
          Promise.resolve(transport.close()).catch(() => {});
          return;
        }
        transports.set(data.descriptor, transport);
        subscriber.next({ data });
        subscriber.complete();
      })
      .catch(error => {
        if (cancelled) return;
        subscriber.error(serializeError(error));
      });

    return () => {
      cancelled = true;
    };
  });

/**
 * Exchanges a single APDU with the device.
 *
 * Emits a single response whose `data` field holds the hex string of the
 * response buffer, then completes. Emits a `DisconnectedDeviceDuringOperation`
 * error if no transport is open for the descriptor or if the exchange fails.
 */
export const transportExchange = ({ data }: MessagesMap["transport:exchange"]) =>
  new Observable<DataResponse>(subscriber => {
    const transport = transports.get(data.descriptor);
    if (!transport) {
      subscriber.error(
        serializeError(
          new DisconnectedDeviceDuringOperation("No open transport for the given descriptor"),
        ),
      );
      return;
    }

    let cancelled = false;

    transport
      .exchange(Buffer.from(data.apduHex, "hex"))
      .then(response => {
        if (cancelled) return;
        subscriber.next({ data: response.toString("hex") });
        subscriber.complete();
      })
      .catch(error => {
        if (cancelled) return;
        subscriber.error(
          serializeError(new DisconnectedDeviceDuringOperation(getErrorMessage(error))),
        );
      });

    return () => {
      cancelled = true;
    };
  });

/**
 * Exchanges an ordered list of APDUs with the device.
 *
 * Emits one response per APDU: `{ data: <hex string> }` on success or
 * `{ error: { name, message } }` on failure, then completes. Emits a single
 * `DisconnectedDeviceDuringOperation` error if no transport is open.
 */
export const transportExchangeBulk = ({ data }: MessagesMap["transport:exchangeBulk"]) =>
  new Observable<BulkResponse>(subscriber => {
    const transport = transports.get(data.descriptor);
    if (!transport) {
      subscriber.error(
        serializeError(
          new DisconnectedDeviceDuringOperation("No open transport for the given descriptor"),
        ),
      );
      return;
    }

    let cancelled = false;

    (async () => {
      for (const apduHex of data.apdusHex) {
        if (cancelled) return;
        try {
          const response = await transport.exchange(Buffer.from(apduHex, "hex"));
          if (cancelled) return;
          subscriber.next({ data: response.toString("hex") });
        } catch (error) {
          if (cancelled) return;
          subscriber.next({
            error: {
              name: "DisconnectedDeviceDuringOperation",
              message: getErrorMessage(error),
            },
          });
        }
      }
      if (!cancelled) subscriber.complete();
    })();

    return () => {
      cancelled = true;
    };
  });

/**
